import os
calls = [('/data/secret.txt', 'r'), ('/data/sealed/f.txt', 'r'), ('/ro/new.txt', 'w'), ('/data/open.txt', 'r')]
for path, mode in calls:
    try:
        with open(path, mode) as f:
            if mode == 'r':
                f.read()
            else:
                f.write('x')
        print('opened')
    except OSError as e:
        print(type(e).__name__)
print(' '.join(sorted(os.listdir('/data'))))

