const fsp = require('node:fs').promises
const calls = [
  () => fsp.readFile('/data/secret.txt'),
  () => fsp.readFile('/data/sealed/f.txt'),
  () => fsp.writeFile('/ro/new.txt', 'x'),
  () => fsp.readFile('/data/open.txt'),
]
for (const call of calls) {
  try {
    await call()
    console.log('opened')
  } catch (e) {
    console.log(e.code)
  }
}
console.log((await fsp.readdir('/data')).sort().join(' '))

